; Zoom: cursor limits
; $32be-$32d6

; Keeps the cursor in the zoom limits: cursor_x at most $7e (when the pad is touched), cursor_y at most $af. X and Y are the cursor point.
zoom_clamp_cursor
        ldx cursor_x
        cpx #$ff
        beq zoom_clamp_y
        cpx #$7f
        bcc zoom_clamp_y
        ldx #$7e
        stx cursor_x
zoom_clamp_y
        ldy cursor_y
        cpy #$b0
        bcc zoom_clamp_done
        ldy #$af
        sty cursor_y
zoom_clamp_done
        rts
